<?php
/**
 * Generated by clone2theme. Keep this file small: styling lives in theme.json.
 */

add_action(
	'wp_enqueue_scripts',
	function () {
		wp_enqueue_style( 'c2t-style', get_stylesheet_uri(), array(), wp_get_theme()->get( 'Version' ) );
	}
);

// Pattern categories for the sections and repeated items clone2theme found on the page.
add_action(
	'init',
	function () {
		register_block_pattern_category( 'c2t-sections', array( 'label' => __( 'Page sections', 'c2t' ) ) );
		register_block_pattern_category( 'c2t-items', array( 'label' => __( 'Repeating items', 'c2t' ) ) );
	}
);

// "No bullets" list style: many sites draw link lists and menus without markers.
add_action(
	'init',
	function () {
		register_block_style(
			'core/list',
			array(
				'name'         => 'plain',
				'label'        => __( 'No bullets', 'c2t' ),
				'inline_style' => '.wp-block-list.is-style-plain{list-style:none;padding-left:0}',
			)
		);
	}
);
